<template>
  <view class="detail-page">
    <view v-if="loading" class="state-card">正在读取样衣单...</view>
    <view v-else-if="errorMessage" class="state-card"><text>{{ errorMessage }}</text><button @click="loadDetail">重新加载</button></view>
    <template v-else-if="detail">
      <view class="summary-card"><view><text class="title">{{ order.patternTitle }}</text><text class="pill">{{ statusLabel }}</text></view><text class="meta">{{ order.sampleOrderNo }} · {{ order.patternVersionNo }} · 第 {{ order.currentRound }} 轮</text><text class="meta">工厂：{{ order.factoryName || '待确认' }}　预计：{{ order.expectedAt || '待确认' }}</text><text class="notice">{{ order.status === 'confirmed' ? '样衣已确认，尚未创建小单生产订单。' : '当前仍处于样衣验证阶段，不可作为正式生产完成状态。' }}</text></view>

      <view class="section-card"><view class="section-head"><text>面料与要求</text><text>创建时记录</text></view><view class="info-list"><view><text>面料</text><text>{{ order.material.name || '未填写' }}</text></view><view><text>成分</text><text>{{ order.material.composition || '未填写' }}</text></view><view><text>颜色</text><text>{{ order.material.color || '未填写' }}</text></view><view><text>打样要求</text><text>{{ order.requirements || '未填写' }}</text></view></view></view>

      <view class="section-card"><view class="section-head"><text>样衣照片</text><text>稳定云文件</text></view><view v-if="photoPreviews.length" class="photo-grid"><image v-for="item in photoPreviews" :key="item.fileId" :src="item.url" mode="aspectFill" @click="previewPhoto(item)" /></view><text v-else class="empty-line">当前轮次尚未上传样衣照片。</text><button v-if="access.canUpload" class="upload-button" :disabled="uploading" @click="choosePhotos">{{ uploading ? '上传中...' : '上传当前轮次样衣照片' }}</button><textarea v-if="access.canUpload" v-model="factoryNote" maxlength="500" placeholder="补充本轮打样说明（可选）" /></view>

      <view class="section-card"><view class="section-head"><text>修改问题</text><text>{{ openIssueCount }} 项待处理</text></view><view v-if="issues.length" class="issue-list"><view v-for="issue in issues" :key="issue.issueId"><view><text>{{ severityLabel(issue.severity) }} · {{ issue.category || '其他' }}</text><text :class="`issue-${issue.status}`">{{ issue.status === 'resolved' ? '已处理' : '待处理' }}</text></view><text>{{ issue.description }}</text><button v-if="issue.status === 'open' && access.canUpload" @click="resolveIssue(issue)">标记已处理</button></view></view><text v-else class="empty-line">暂无修改问题。</text><template v-if="access.canReview"><textarea v-model="issueDescription" maxlength="500" placeholder="需要修改时，填写具体部位、问题和预期结果。" /><view class="select-row"><picker :range="severityOptions" range-key="label" :value="severityIndex" @change="severityIndex = Number($event.detail.value) || 0"><view>{{ severityOptions[severityIndex].label }} ></view></picker><input v-model="issueLocation" maxlength="80" placeholder="问题部位（可选）" /></view></template></view>

      <view class="section-card"><view class="section-head"><text>修改轮次</text><text>历史不可覆盖</text></view><view class="round-list"><view v-for="round in rounds" :key="round.sampleRoundId"><text>第 {{ round.roundNo }} 轮</text><text>{{ label(round.status) }} · {{ formatDate(round.updatedAt) }}</text></view></view></view>
      <view class="section-card"><view class="section-head"><text>协作记录</text><text>云端审计</text></view><view class="event-list"><view v-for="item in events" :key="item.eventId"><text>{{ actionLabel(item.action) }}</text><text>{{ formatDate(item.createdAt) }}</text></view></view></view>

      <view class="action-card">
        <button v-if="access.canSubmit" class="primary" :disabled="operating" @click="runSimple('submit')">提交工厂接单</button>
        <button v-if="access.canAccept" class="primary" :disabled="operating" @click="runSimple('accept')">接单并开始打样</button>
        <button v-if="access.canUpload" class="primary" :disabled="operating || !photoAssetIds.length" @click="completeRound">提交样衣完成</button>
        <button v-if="access.canSubmitReview" class="primary" :disabled="operating" @click="runSimple('submit_review')">提交样衣验收</button>
        <button v-if="access.canReview" class="danger" :disabled="operating || !issueDescription.trim()" @click="requestChanges">需要修改</button>
        <button v-if="access.canReview" class="primary" :disabled="operating || openIssueCount > 0" @click="confirmSample">确认样衣</button>
        <button v-if="order.status === 'changes_requested' && access.canStart" class="primary" :disabled="operating" @click="startResampling">开始再次打样</button>
        <button v-if="order.status === 'confirmed'" class="primary production" :disabled="operating" @click="openManualSampling">联系人工打样</button>
        <button v-if="access.canCancel" class="secondary" :disabled="operating" @click="cancelOrder">取消样衣单</button>
      </view>
      <view class="safe-space"></view>
    </template>
  </view>
</template>

<script>
import { acceptSampleOrder, cancelSampleOrder, completeSampleRound, confirmSampleOrder, getSampleOrder, requestSampleChanges, resolveSampleIssue, startSampleResampling, submitSampleForReview, submitSampleOrder } from '../../utils/sample/sampleRepository.js'
import { getSampleStatusLabel } from '../../utils/sample/sampleState.js'
import { getTemporaryFileUrl, uploadUnifiedFiles } from '../../utils/upload/unifiedUploadService.js'

export default {
  data() { return { sampleOrderId: '', loading: true, operating: false, uploading: false, errorMessage: '', detail: null, photoAssetIds: [], photoPreviews: [], factoryNote: '', issueDescription: '', issueLocation: '', severityIndex: 1, severityOptions: [{ value: 'low', label: '轻微问题' }, { value: 'medium', label: '一般问题' }, { value: 'high', label: '严重问题' }] } },
  computed: { order() { return (this.detail && this.detail.order) || { material: {} } }, access() { return (this.detail && this.detail.access) || {} }, rounds() { return (this.detail && this.detail.rounds) || [] }, issues() { return (this.detail && this.detail.issues) || [] }, events() { return (this.detail && this.detail.events) || [] }, statusLabel() { return getSampleStatusLabel(this.order.status) }, openIssueCount() { return this.issues.filter((item) => item.status === 'open').length } },
  onLoad(options = {}) { this.sampleOrderId = String(options.sampleOrderId || ''); this.loadDetail() },
  methods: {
    async loadDetail() { this.loading = true; this.errorMessage = ''; const result = await getSampleOrder(this.sampleOrderId); if (!result.ok) { this.detail = null; this.errorMessage = result.message || '样衣单暂时无法读取。' } else { this.detail = result.data; const latest = result.data.rounds[0] || {}; this.photoAssetIds = latest.photoAssetIds || []; await this.resolvePhotos(this.photoAssetIds) } this.loading = false },
    async resolvePhotos(ids) { const items = []; for (const fileId of ids) { const result = await getTemporaryFileUrl(fileId); if (result.success && result.tempUrl) items.push({ fileId, url: result.tempUrl }) } this.photoPreviews = items },
    choosePhotos() { if (this.uploading) return; uni.chooseImage({ count: Math.max(1, 6 - this.photoAssetIds.length), sizeType: ['compressed'], sourceType: ['album', 'camera'], success: async (result) => { this.uploading = true; const files = (result.tempFiles || []).map((file, index) => ({ ...file, path: file.path || (result.tempFilePaths || [])[index] })); const uploaded = await uploadUnifiedFiles(files, { assetType: 'sample_image', maxCount: 6, targetType: 'sample_order', targetId: this.sampleOrderId, relation: `sample_round_${this.order.currentRound}` }); this.uploading = false; if (!uploaded.success) return uni.showToast({ title: '部分或全部样衣照片上传失败', icon: 'none' }); this.photoAssetIds = [...new Set([...this.photoAssetIds, ...uploaded.results.map((item) => item.fileId).filter(Boolean)])].slice(0, 6); await this.resolvePhotos(this.photoAssetIds); uni.showToast({ title: '样衣照片已上传', icon: 'success' }) } }) },
    previewPhoto(item) { uni.previewImage({ current: item.url, urls: this.photoPreviews.map((photo) => photo.url) }) },
    async run(action, successText) { if (this.operating) return; this.operating = true; const result = await action(); this.operating = false; if (!result.ok) return uni.showToast({ title: result.message || '操作失败', icon: 'none' }); uni.showToast({ title: successText, icon: 'success' }); await this.loadDetail() },
    runSimple(action) { const map = { submit: () => submitSampleOrder(this.sampleOrderId), accept: () => acceptSampleOrder(this.sampleOrderId), submit_review: () => submitSampleForReview(this.sampleOrderId) }; return this.run(map[action], action === 'accept' ? '已接单' : '已提交') },
    completeRound() { return this.run(() => completeSampleRound({ sampleOrderId: this.sampleOrderId, photoAssetIds: this.photoAssetIds, factoryNote: this.factoryNote }), '样衣照片已提交') },
    requestChanges() { return this.run(() => requestSampleChanges({ sampleOrderId: this.sampleOrderId, issues: [{ category: 'fit_or_craft', severity: this.severityOptions[this.severityIndex].value, location: this.issueLocation, description: this.issueDescription }] }), '已提交修改意见') },
    startResampling() { return this.run(() => startSampleResampling({ sampleOrderId: this.sampleOrderId, note: '按未关闭问题开始下一轮打样' }), '已开始再次打样') },
    resolveIssue(issue) { uni.showModal({ title: '标记问题已处理', editable: true, placeholderText: '填写处理说明', success: ({ confirm, content }) => { if (confirm) this.run(() => resolveSampleIssue({ sampleOrderId: this.sampleOrderId, issueId: issue.issueId, resolutionNote: content }), '问题已处理') } }) },
    confirmSample() { uni.showModal({ title: '确认样衣', content: '确认仅代表本轮样衣验收通过，不会自动创建生产订单。', confirmText: '确认样衣', success: ({ confirm }) => { if (confirm) this.run(() => confirmSampleOrder({ sampleOrderId: this.sampleOrderId }), '样衣已确认') } }) },
    cancelOrder() { uni.showModal({ title: '取消样衣单', editable: true, placeholderText: '请填写取消原因', confirmColor: '#d92d20', success: ({ confirm, content }) => { if (confirm) this.run(() => cancelSampleOrder({ sampleOrderId: this.sampleOrderId, reason: content }), '样衣单已取消') } }) },
    openManualSampling() { uni.navigateTo({ url: '/pages/service-request/service-request', fail: () => uni.showToast({ title: '人工打样需求页暂时无法打开', icon: 'none' }) }) },
    label(value) { return getSampleStatusLabel(value) }, severityLabel(value) { return ({ low: '轻微', medium: '一般', high: '严重' })[value] || '一般' }, actionLabel(value) { return ({ create_draft: '创建草稿', update_draft: '更新草稿', submit: '提交工厂接单', accept: '工厂接单并开始打样', complete_sample: '提交样衣完成', submit_review: '提交验收', request_changes: '提出修改', start_resampling: '开始再次打样', confirm: '确认样衣', cancel: '取消样衣单' })[value] || '协作更新' }, formatDate(value) { const date = value ? new Date(value) : null; return date && Number.isFinite(date.getTime()) ? date.toLocaleString('zh-CN', { hour12: false }) : '时间待同步' }
  }
}
</script>

<style scoped>
.detail-page{min-height:100vh;padding:24rpx;background:#f5f6fa;color:#1f2937;box-sizing:border-box}.state-card{display:flex;align-items:center;flex-direction:column;padding:80rpx 28rpx;border-radius:18rpx;background:#fff;color:#667085;text-align:center}.state-card button{height:72rpx;margin-top:20rpx;border:0;border-radius:12rpx;background:#1677ff;color:#fff;line-height:72rpx}.summary-card,.section-card,.action-card{padding:26rpx;border:1rpx solid #e4e9f0;border-radius:18rpx;background:#fff}.summary-card>view,.section-head,.issue-list>view>view{display:flex;align-items:center;justify-content:space-between;gap:16rpx}.title{font-size:31rpx;font-weight:700}.pill{padding:7rpx 12rpx;border-radius:8rpx;background:#fff4e5;color:#9a5700;font-size:20rpx}.meta,.notice{display:block;margin-top:10rpx;color:#667085;font-size:22rpx}.notice{padding:14rpx;border-radius:10rpx;background:#fff8e8;color:#765f39;line-height:1.5}.section-card{margin-top:18rpx}.section-head text:first-child{font-size:28rpx;font-weight:700}.section-head text:last-child{color:#7b8495;font-size:20rpx}.info-list,.round-list,.event-list,.issue-list{margin-top:14rpx}.info-list view,.round-list view,.event-list view{display:flex;justify-content:space-between;gap:20rpx;padding:15rpx 0;border-bottom:1rpx solid #edf0f4;font-size:22rpx}.info-list text:first-child{color:#667085}.info-list text:last-child{max-width:70%;text-align:right}.photo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10rpx;margin-top:16rpx}.photo-grid image{width:100%;height:190rpx;border-radius:10rpx;background:#f2f4f7}.upload-button{height:72rpx;margin-top:16rpx;border:1rpx dashed #98bfff;border-radius:12rpx;background:#edf6ff;color:#1677ff;font-size:22rpx;line-height:72rpx}.section-card textarea{width:100%;height:150rpx;margin-top:14rpx;padding:16rpx;border-radius:12rpx;background:#f6f8fa;font-size:22rpx;box-sizing:border-box}.empty-line{display:block;margin-top:16rpx;color:#667085;font-size:22rpx}.issue-list>view{padding:16rpx 0;border-bottom:1rpx solid #edf0f4}.issue-list>view>text{display:block;margin-top:8rpx;color:#475467;font-size:22rpx;line-height:1.5}.issue-list button{height:60rpx;margin:12rpx 0 0;border:1rpx solid #b9d9ff;border-radius:10rpx;background:#fff;color:#1677ff;font-size:20rpx;line-height:60rpx}.issue-open{color:#b54708}.issue-resolved{color:#177245}.select-row{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:12rpx}.select-row view,.select-row input{height:70rpx;padding:0 16rpx;border-radius:10rpx;background:#f6f8fa;font-size:21rpx;line-height:70rpx;box-sizing:border-box}.action-card{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:18rpx}.action-card button{height:76rpx;margin:0;border-radius:12rpx;font-size:21rpx;font-weight:700;line-height:76rpx}.primary{border:0;background:#1677ff;color:#fff}.secondary{border:1rpx solid #b9d9ff;background:#fff;color:#1677ff}.danger{border:1rpx solid #f2b8b5;background:#fff5f5;color:#b42318}.safe-space{height:calc(42rpx + env(safe-area-inset-bottom))}@media screen and (max-width:350px){.detail-page{padding:18rpx}.action-card{grid-template-columns:1fr}.photo-grid{grid-template-columns:repeat(2,1fr)}}
</style>
